<?php
declare(strict_types=1);
require_once __DIR__ . '/../modules/auth.php';require_once __DIR__ . '/../modules/community-groups.php';require_login();start_app_session();
if(empty($_SESSION['community_content_csrf']))$_SESSION['community_content_csrf']=bin2hex(random_bytes(32));$csrf=(string)$_SESSION['community_content_csrf'];$error='';$flash='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!hash_equals($csrf,(string)($_POST['csrf']??''))){http_response_code(403);exit('Sessão expirada.');}
    try{community_resource_create($_POST);$flash='Conteúdo publicado no grupo.';}catch(DomainException $e){$error=$e->getMessage();}catch(Throwable $e){error_log('[AFFILIEY] community content: '.$e->getMessage());$error='Não foi possível publicar. Revise os dados e tente novamente.';}
}
$groups=community_group_list_for_producer();$selected=(string)($_GET['group']??($groups[0]['id']??''));$resources=$selected!==''?community_resource_list_for_producer($selected):[];
function cc_e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Conteúdos dos grupos — AFFILIEY</title><link rel="stylesheet" href="/assets/css/app-theme.css?v=3"><link rel="stylesheet" href="/assets/css/brand.css?v=affiliey4"><link rel="stylesheet" href="/assets/css/workspace-premium.css?v=3"><link rel="stylesheet" href="/assets/css/profile-environments.css?v=3"><link rel="stylesheet" href="/assets/css/typography.css?v=1"></head><body class="app-shell"><header class="topbar"><a class="brand" href="dashboard.php"><img class="brand-logo" src="/brand/affiliey-logo-dark.png" alt="AFFILIEY"></a><nav class="main-nav"><?= app_workspace_navigation() ?></nav><div class="top-actions"><?= app_header_account_tools() ?><span><?= cc_e(current_user()['name']??'') ?></span><a href="login.php?logout=1">Sair</a></div></header><main class="profile-page"><div class="profile-heading"><div><span class="profile-eyebrow">PUBLICAÇÃO POR GRUPO</span><h1>Conteúdos e comunicados</h1><p>Materiais, avisos e reuniões ficam visíveis somente aos participantes ativos do grupo escolhido.</p></div></div><?php if($error): ?><p class="message error" role="alert"><?= cc_e($error) ?></p><?php endif; ?><?php if($flash): ?><p class="message success" role="status"><?= cc_e($flash) ?></p><?php endif; ?><?php if(!$groups): ?><section class="profile-empty"><h2>Crie um grupo primeiro</h2><p>Os conteúdos são publicados dentro de um grupo.</p><a class="button primary" href="communities.php">Ir para Meus grupos</a></section><?php else: ?><section class="profile-panel"><form method="get" class="community-form"><label>Grupo<select name="group" onchange="this.form.submit()"><?php foreach($groups as $group): ?><option value="<?= cc_e($group['id']) ?>" <?= $selected===$group['id']?'selected':'' ?>><?= cc_e($group['name']) ?></option><?php endforeach; ?></select></label></form></section><?php if(app_user_can('communities','edit')): ?><section class="profile-panel"><h2>Nova publicação</h2><form method="post" class="community-form"><input type="hidden" name="csrf" value="<?= cc_e($csrf) ?>"><input type="hidden" name="group_id" value="<?= cc_e($selected) ?>"><label>Tipo<select name="resource_type"><option value="content">Conteúdo/material</option><option value="announcement">Comunicado</option><option value="meeting">Reunião/treinamento</option></select></label><label>Título<input name="title" maxlength="160" required></label><label>Descrição<textarea name="body" maxlength="10000" rows="4"></textarea></label><label>Link HTTPS<input type="url" name="resource_url" placeholder="https://..."></label><label>Data e hora<input type="datetime-local" name="starts_at"></label><button class="button primary" type="submit">Publicar</button></form></section><?php endif; ?><section class="profile-panel"><h2>Publicações do grupo</h2><?php if(!$resources): ?><p class="profile-muted">Nenhum conteúdo publicado neste grupo.</p><?php else: ?><div class="profile-resource-list"><?php foreach($resources as $item): ?><article><div><span class="profile-product-platform"><?= cc_e(['content'=>'CONTEÚDO','announcement'=>'COMUNICADO','meeting'=>'REUNIÃO'][$item['resource_type']]??strtoupper($item['resource_type'])) ?><?= $item['starts_at']?' · '.cc_e(date('d/m/Y H:i',strtotime($item['starts_at']))):'' ?></span><h3><?= cc_e($item['title']) ?></h3><p><?= nl2br(cc_e($item['body'])) ?></p><?php if($item['resource_url']): ?><a href="<?= cc_e($item['resource_url']) ?>" target="_blank" rel="noopener noreferrer">Abrir recurso ↗</a><?php endif; ?></div></article><?php endforeach; ?></div><?php endif; ?></section><?php endif; ?></main></body></html>
